// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "./SwapStepsConfigStore.sol";

/* =========================================================
 * External DEX interfaces — quoting only
 * ========================================================= */

/// @dev Uniswap V2 / SushiSwap V2 / Camelot V2 routers all expose this.
interface IUniswapV2RouterQuote {
    function getAmountsOut(
        uint256 amountIn,
        address[] calldata path
    ) external view returns (uint256[] memory amounts);
}

/// @dev Uniswap V3 / Sushi V3 pool — direct swap simulation for quoting.
///      Same signature as Algebra pools.
interface IV3PoolQuote {
    function token0() external view returns (address);
    function token1() external view returns (address);

    function swap(
        address recipient,
        bool zeroForOne,
        int256 amountSpecified,
        uint160 sqrtPriceLimitX96,
        bytes calldata data
    ) external returns (int256 amount0, int256 amount1);
}

/// @dev Algebra (Camelot V3) pool — same swap signature, different callback name.
interface IAlgebraPoolQuote {
    function token0() external view returns (address);
    function token1() external view returns (address);

    function swap(
        address recipient,
        bool zeroToOne,
        int256 amountSpecified,
        uint160 limitSqrtPrice,
        bytes calldata data
    ) external returns (int256 amount0, int256 amount1);
}

/* =========================================================
 * ArbQuoter — read-only quoting via DEX Router / direct pool simulation
 *
 * V2 / CamelotV2 (kind=0,2): router.getAmountsOut
 * V3            (kind=1):     direct pool.swap + uniswapV3SwapCallback revert
 * Algebra       (kind=3):     direct pool.swap + algebraSwapCallback revert
 * ========================================================= */
contract ArbQuoter is Ownable {

    // =========================================================
    // State
    // =========================================================

    SwapStepsConfigStore public configStore;

    // =========================================================
    // Errors
    // =========================================================

    error ZERO_ADDRESS();
    error UNKNOWN_KIND(uint8 kind);
    error NO_STEPS();

    /// @dev Thrown inside swap callbacks to carry the quote result back via revert.
    error QuoteCallbackResult(uint256 amountOut);

    // =========================================================
    // Constants — Algebra sqrt price limits (same as AlgebraSwapLib)
    // =========================================================

    uint160 private constant ALG_MIN_SQRT_RATIO = 4295128739;
    uint160 private constant ALG_MAX_SQRT_RATIO =
        1461446703485210103287273052203988822378723970342;

    // =========================================================
    // Structs — results
    // =========================================================

    struct QuoteResult {
        uint256 index;
        uint256 amountOut;
        bool    success;
    }

    struct QuoteBatchResult {
        QuoteResult[] quotes;
        uint256 blockNumber;
        uint256 gasUsed;
    }

    struct RoundTripResult {
        uint256 index;
        uint256 buyAmountOut;   // amountOut of forward quote
        uint256 sellAmountOut;  // amountOut of reverse quote (≈ how much tokenIn you get back)
        int256  profit;         // int256(sellAmountOut) - int256(amountIn)
        bool    success;
    }

    struct RoundTripBatchResult {
        RoundTripResult[] trips;
        uint256 blockNumber;
        uint256 gasUsed;
    }

    // =========================================================
    // Constructor
    // =========================================================

    constructor(address initialOwner) Ownable(initialOwner) {}

    // =========================================================
    // Setters (onlyOwner)
    // =========================================================

    function setConfigStore(address _configStore) external onlyOwner {
        if (_configStore == address(0)) revert ZERO_ADDRESS();
        configStore = SwapStepsConfigStore(_configStore);
    }

    // =========================================================
    // Swap callbacks — always revert with the quote result
    // =========================================================

    /// @dev Called by Uniswap V3 / Sushi V3 pools during swap simulation.
    function uniswapV3SwapCallback(
        int256 amount0Delta,
        int256 amount1Delta,
        bytes calldata data
    ) external pure {
        _revertWithQuote(amount0Delta, amount1Delta, data);
    }

    /// @dev Called by Algebra (Camelot V3) pools during swap simulation.
    function algebraSwapCallback(
        int256 amount0Delta,
        int256 amount1Delta,
        bytes calldata data
    ) external pure {
        _revertWithQuote(amount0Delta, amount1Delta, data);
    }

    /// @dev Shared callback logic: decode direction, compute amountOut, revert.
    function _revertWithQuote(
        int256 amount0Delta,
        int256 amount1Delta,
        bytes calldata data
    ) internal pure {
        bool zeroForOne = abi.decode(data, (bool));

        uint256 amountOut;
        if (zeroForOne) {
            amountOut = amount1Delta < 0 ? uint256(-amount1Delta) : 0;
        } else {
            amountOut = amount0Delta < 0 ? uint256(-amount0Delta) : 0;
        }

        revert QuoteCallbackResult(amountOut);
    }

    // =========================================================
    // Method 1: quoteExactIn — single step
    // =========================================================

    /// @notice Get a quote for a single swap step.
    function quoteExactIn(
        SwapStepsConfigStore.SwapStep calldata step,
        uint256 amountIn
    ) external returns (uint256 amountOut, bool success) {
        return _quoteExactInSafe(step, amountIn);
    }

    // =========================================================
    // Method 2: quoteExactInBatch — multiple steps
    // =========================================================

    /// @notice Quote all steps directly (calldata).
    function quoteExactInBatch(
        SwapStepsConfigStore.SwapStep[] calldata steps,
        uint256 amountIn
    ) external returns (QuoteBatchResult memory result) {
        uint256 gasStart = gasleft();
        result.quotes = _quoteExactInBatchInternal(steps, amountIn);
        result.blockNumber = block.number;
        result.gasUsed = gasStart - gasleft();
    }

    /// @notice Quote all steps by store key.
    function quoteExactInBatchByKey(
        bytes32 key,
        uint256 amountIn
    ) external returns (QuoteBatchResult memory result) {
        uint256 gasStart = gasleft();
        SwapStepsConfigStore.SwapStep[] memory raw = configStore.getConfig(key);
        result.quotes = _quoteExactInBatchMem(raw, amountIn);
        result.blockNumber = block.number;
        result.gasUsed = gasStart - gasleft();
    }

    // =========================================================
    // Method 3: quoteRoundTrip — single step (approximation)
    // =========================================================

    /// @notice Quote forward + reverse for a single step.
    ///         Approximation: ExactIn forward, then ExactIn reverse with buyAmountOut.
    function quoteRoundTrip(
        SwapStepsConfigStore.SwapStep calldata step,
        uint256 amountIn
    ) external returns (RoundTripResult memory) {
        return _quoteRoundTripInternal(step, amountIn, 0);
    }

    // =========================================================
    // Method 4: quoteRoundTripBatch — multiple steps
    // =========================================================

    /// @notice Round-trip quote all steps directly (calldata).
    function quoteRoundTripBatch(
        SwapStepsConfigStore.SwapStep[] calldata steps,
        uint256 amountIn
    ) external returns (RoundTripBatchResult memory result) {
        uint256 gasStart = gasleft();
        result.trips = _quoteRoundTripBatchCalldata(steps, amountIn);
        result.blockNumber = block.number;
        result.gasUsed = gasStart - gasleft();
    }

    /// @notice Round-trip quote all steps by store key.
    function quoteRoundTripBatchByKey(
        bytes32 key,
        uint256 amountIn
    ) external returns (RoundTripBatchResult memory result) {
        uint256 gasStart = gasleft();
        SwapStepsConfigStore.SwapStep[] memory raw = configStore.getConfig(key);
        result.trips = _quoteRoundTripBatchMem(raw, amountIn);
        result.blockNumber = block.number;
        result.gasUsed = gasStart - gasleft();
    }

    // =========================================================
    // Internal — core quoting logic
    // =========================================================

    /// @dev Quote a single step. Reverts on unknown kind.
    function _quoteExactIn(
        SwapStepsConfigStore.SwapStep memory step,
        uint256 amountIn
    ) internal returns (uint256 amountOut) {
        uint8 kind = step.kind;

        // V2_EXACT_IN (kind=0) or CAMELOT_V2_EXACT_IN (kind=2)
        if (kind == 0 || kind == 2) {
            address[] memory path = step.path;
            if (path.length < 2) {
                path = new address[](2);
                path[0] = step.tokenIn;
                path[1] = step.tokenOut;
            }
            uint256[] memory amounts = IUniswapV2RouterQuote(step.router)
                .getAmountsOut(amountIn, path);
            return amounts[amounts.length - 1];
        }

        // V3_POOL_EXACT_IN (kind=1) — direct pool swap simulation
        if (kind == 1) {
            return _quoteV3ExactIn(step.pool, step.tokenIn, amountIn);
        }

        // ALGEBRA_POOL_EXACT_IN (kind=3) — direct pool swap simulation
        if (kind == 3) {
            return _quoteAlgebraExactIn(step.pool, step.tokenIn, amountIn);
        }

        revert UNKNOWN_KIND(kind);
    }

    /// @dev Quote Uniswap V3 / Sushi V3 pool via swap simulation + callback-revert.
    ///      Pool calls uniswapV3SwapCallback → we revert with QuoteCallbackResult(amountOut).
    function _quoteV3ExactIn(
        address pool,
        address tokenIn,
        uint256 amountIn
    ) internal returns (uint256 amountOut) {
        address t0 = IV3PoolQuote(pool).token0();
        bool zeroForOne = (tokenIn == t0);

        uint160 limit = zeroForOne
            ? (ALG_MIN_SQRT_RATIO + 1)
            : (ALG_MAX_SQRT_RATIO - 1);

        bytes memory cbData = abi.encode(zeroForOne);

        try IV3PoolQuote(pool).swap(
            address(this),
            zeroForOne,
            int256(amountIn),
            limit,
            cbData
        ) {
            revert("V3_QUOTE_UNEXPECTED_SUCCESS");
        } catch (bytes memory reason) {
            return _decodeQuoteRevert(reason);
        }
    }

    /// @dev Quote Algebra (Camelot V3) pool via swap simulation + callback-revert.
    ///      Pool calls algebraSwapCallback → we revert with QuoteCallbackResult(amountOut).
    function _quoteAlgebraExactIn(
        address pool,
        address tokenIn,
        uint256 amountIn
    ) internal returns (uint256 amountOut) {
        address t0 = IAlgebraPoolQuote(pool).token0();
        bool zeroToOne = (tokenIn == t0);

        uint160 limit = zeroToOne
            ? (ALG_MIN_SQRT_RATIO + 1)
            : (ALG_MAX_SQRT_RATIO - 1);

        bytes memory cbData = abi.encode(zeroToOne);

        try IAlgebraPoolQuote(pool).swap(
            address(this),
            zeroToOne,
            int256(amountIn),
            limit,
            cbData
        ) {
            revert("ALGEBRA_QUOTE_UNEXPECTED_SUCCESS");
        } catch (bytes memory reason) {
            return _decodeQuoteRevert(reason);
        }
    }

    /// @dev Decode QuoteCallbackResult(uint256) from revert data.
    function _decodeQuoteRevert(bytes memory reason) internal pure returns (uint256 amountOut) {
        bytes4 expected = QuoteCallbackResult.selector;
        if (reason.length >= 36) {
            bytes4 sel;
            assembly { sel := mload(add(reason, 32)) }
            if (sel == expected) {
                assembly { amountOut := mload(add(reason, 36)) }
                return amountOut;
            }
        }
        // Unknown revert — propagate
        assembly { revert(add(reason, 32), mload(reason)) }
    }

    /// @dev Safe wrapper: returns (amountOut, success). Does not revert on failure.
    function _quoteExactInSafe(
        SwapStepsConfigStore.SwapStep memory step,
        uint256 amountIn
    ) internal returns (uint256 amountOut, bool success) {
        try this._quoteExactInExternal(step, amountIn) returns (uint256 out) {
            return (out, true);
        } catch {
            return (0, false);
        }
    }

    /// @dev External wrapper needed for try/catch on internal memory-param function.
    ///      Must only be called by this contract itself.
    function _quoteExactInExternal(
        SwapStepsConfigStore.SwapStep calldata step,
        uint256 amountIn
    ) external returns (uint256) {
        require(msg.sender == address(this), "SELF_ONLY");
        return _quoteExactIn(step, amountIn);
    }

    // =========================================================
    // Internal — batch helpers
    // =========================================================

    /// @dev Batch from calldata array.
    function _quoteExactInBatchInternal(
        SwapStepsConfigStore.SwapStep[] calldata steps,
        uint256 amountIn
    ) internal returns (QuoteResult[] memory results) {
        uint256 n = steps.length;
        results = new QuoteResult[](n);
        for (uint256 i = 0; i < n; i++) {
            (uint256 out, bool ok) = _quoteExactInSafe(steps[i], amountIn);
            results[i] = QuoteResult({ index: i, amountOut: out, success: ok });
        }
    }

    /// @dev Batch from memory array (for store-based calls).
    function _quoteExactInBatchMem(
        SwapStepsConfigStore.SwapStep[] memory steps,
        uint256 amountIn
    ) internal returns (QuoteResult[] memory results) {
        uint256 n = steps.length;
        results = new QuoteResult[](n);
        for (uint256 i = 0; i < n; i++) {
            (uint256 out, bool ok) = _quoteExactInSafe(steps[i], amountIn);
            results[i] = QuoteResult({ index: i, amountOut: out, success: ok });
        }
    }

    // =========================================================
    // Internal — round-trip helpers
    // =========================================================

    /// @dev Round-trip for a single step (memory).
    function _quoteRoundTripInternal(
        SwapStepsConfigStore.SwapStep memory step,
        uint256 amountIn,
        uint256 index
    ) internal returns (RoundTripResult memory r) {
        r.index = index;

        // Forward: tokenIn → tokenOut
        (uint256 buyOut, bool buyOk) = _quoteExactInSafe(step, amountIn);
        if (!buyOk || buyOut == 0) {
            r.success = false;
            return r;
        }
        r.buyAmountOut = buyOut;

        // Reverse: tokenOut → tokenIn (invert the step)
        SwapStepsConfigStore.SwapStep memory inv = _invertStep(step);
        (uint256 sellOut, bool sellOk) = _quoteExactInSafe(inv, buyOut);
        if (!sellOk) {
            r.success = false;
            return r;
        }
        r.sellAmountOut = sellOut;
        r.profit = int256(sellOut) - int256(amountIn);
        r.success = true;
    }

    /// @dev Batch round-trip from calldata.
    function _quoteRoundTripBatchCalldata(
        SwapStepsConfigStore.SwapStep[] calldata steps,
        uint256 amountIn
    ) internal returns (RoundTripResult[] memory results) {
        uint256 n = steps.length;
        results = new RoundTripResult[](n);
        for (uint256 i = 0; i < n; i++) {
            results[i] = _quoteRoundTripInternal(steps[i], amountIn, i);
        }
    }

    /// @dev Batch round-trip from memory (store-based).
    function _quoteRoundTripBatchMem(
        SwapStepsConfigStore.SwapStep[] memory steps,
        uint256 amountIn
    ) internal returns (RoundTripResult[] memory results) {
        uint256 n = steps.length;
        results = new RoundTripResult[](n);
        for (uint256 i = 0; i < n; i++) {
            results[i] = _quoteRoundTripInternal(steps[i], amountIn, i);
        }
    }

    // =========================================================
    // Internal — step inversion
    // =========================================================

    /// @dev Invert a step: swap tokenIn↔tokenOut, reverse path. Pool stays the same (V3/Algebra).
    function _invertStep(
        SwapStepsConfigStore.SwapStep memory s
    ) internal pure returns (SwapStepsConfigStore.SwapStep memory inv) {
        inv.kind    = s.kind;
        inv.router  = s.router;
        inv.pool    = s.pool;
        inv.tokenIn = s.tokenOut;   // reversed
        inv.tokenOut = s.tokenIn;   // reversed

        // Reverse path for V2 (length 2)
        if (s.path.length == 2) {
            address[] memory revPath = new address[](2);
            revPath[0] = s.path[1];
            revPath[1] = s.path[0];
            inv.path = revPath;
        } else {
            inv.path = new address[](0);
        }
    }
}

contracts/SwapStepsConfigStore.sol.content:
// SPDX-License-Identifier: MIT

// Deployed at: 0xfcB158cf91994c31D61e3F7358B5273c8e6729bD

pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";

contract SwapStepsConfigStore is Ownable {
    // ============ Errors ============
    error BAD_PATH_LEN();
    error KEY_NOT_FOUND();

    // ============ Data ============
    struct SwapStep {
        uint8 kind;

        // V2
        address router;
        address[] path;

        // V3 / Algebra
        address pool;

        // common
        address tokenIn;
        address tokenOut;
    }

    mapping(bytes32 => SwapStep[]) private _configs;

    bytes32[] private _keys;
    mapping(bytes32 => uint256) private _keyIndex; // index + 1

    event ConfigSet(bytes32 indexed key, uint256 stepsCount);
    event ConfigDeleted(bytes32 indexed key);

    constructor(address initialOwner) Ownable(initialOwner) {}

    // =========================
    // OWNER-ONLY MUTATIONS
    // =========================

    function setConfig(bytes32 key, SwapStep[] calldata steps) external onlyOwner {
        // add key if new
        if (_keyIndex[key] == 0) {
            _keys.push(key);
            _keyIndex[key] = _keys.length; // index + 1
        }

        delete _configs[key];

        uint256 n = steps.length;
        for (uint256 i = 0; i < n; i++) {
            _configs[key].push();
            SwapStep storage s = _configs[key][i];

            s.kind = steps[i].kind;

            s.router = steps[i].router;
            s.pool = steps[i].pool;

            s.tokenIn = steps[i].tokenIn;
            s.tokenOut = steps[i].tokenOut;

            uint256 pl = steps[i].path.length;
            if (pl == 2) {
                s.path.push(steps[i].path[0]);
                s.path.push(steps[i].path[1]);
            } else if (pl != 0) {
                revert BAD_PATH_LEN();
            }
        }

        emit ConfigSet(key, n);
    }

    function deleteConfig(bytes32 key) external onlyOwner {
        uint256 indexPlusOne = _keyIndex[key];
        if (indexPlusOne == 0) revert KEY_NOT_FOUND();

        delete _configs[key];

        // swap & pop key
        uint256 index = indexPlusOne - 1;
        uint256 lastIndex = _keys.length - 1;

        if (index != lastIndex) {
            bytes32 lastKey = _keys[lastIndex];
            _keys[index] = lastKey;
            _keyIndex[lastKey] = index + 1;
        }

        _keys.pop();
        delete _keyIndex[key];

        emit ConfigDeleted(key);
    }

    // =========================
    // GETTERS
    // =========================

    function getConfig(bytes32 key) external view returns (SwapStep[] memory) {
        return _configs[key];
    }

    function getAllKeys() external view returns (bytes32[] memory) {
        return _keys;
    }

    function getKeysCount() external view returns (uint256) {
        return _keys.length;
    }
}
